// data/kit.json is generated by `npm run kit` from genshin-db plus data/kit-overrides.json (#68, #73).
import { expect, test } from "vitest";
import kit from "../../../data/kit.json";
import overrides from "../../../data/kit-overrides.json";
import tags from "../../../data/tags.json";

type KitEntry = { buffs: { value: number; uptime: number | null }[]; missing?: string };
const characters = kit.characters as Record<string, KitEntry>;

test("every tagged buffer has a kit entry with readable values", () => {
  const buffers = tags.filter((c) => c.roles.includes("buffer") && (c.buffs ?? []).length > 0).map((c) => c.id);
  expect(Object.keys(characters).sort()).toEqual(buffers.sort());
  for (const [id, c] of Object.entries(characters)) {
    if (c.missing) continue;
    expect(c.buffs.length, id).toBeGreaterThan(0);
    for (const b of c.buffs) {
      expect(b.value, id).toBeGreaterThan(0);
      if (b.uptime !== null) expect(b.uptime, id).toBeLessThanOrEqual(1);
    }
  }
});

// Each Moonsign Benediction raises the party's Moonsign by 1 level, which is how ascendantGleamLines counts
// it: so every Moonsign family member must have one, and nobody else.
test("the Moonsign family is exactly the characters with a Moonsign Benediction", { timeout: 60_000 }, async () => {
  const genshindb = (await import("genshin-db")).default;
  const withBenediction = tags
    .filter((c) => {
      const t = genshindb.talents(c.id);
      return [t?.passive1, t?.passive2, t?.passive3, t?.passive4].some((p) => p?.name.startsWith("Moonsign Benediction"));
    })
    .map((c) => c.id);
  const family = tags.filter((c) => (c.families ?? []).includes("moonsign")).map((c) => c.id);
  expect(family.sort()).toEqual(withBenediction.sort());
});

// Lunar and Stellar conversion comes from each character's "Moonsign Benediction" / "Stellar Jubilee"
// passive (#63): tags.json's `converts` must say exactly what that sentence converts into.
test("converts matches the conversion sentence in genshin-db's kit text", { timeout: 60_000 }, async () => {
  const genshindb = (await import("genshin-db")).default;
  const OUTPUTS: Record<string, string> = {
    "Lunar-Charged": "lunar-charged",
    "Lunar-Bloom": "lunar-bloom",
    "Lunar-Crystallize": "lunar-crystallize",
    "Stellar-Conduct": "stellar-conduct",
    "Stellar Swirl": "stellar-swirl",
  };
  const fromKit: Record<string, string[]> = {};
  for (const c of tags) {
    const t = genshindb.talents(c.id);
    for (const p of [t?.passive1, t?.passive2, t?.passive3, t?.passive4]) {
      if (!p || !/^(Moonsign Benediction|Stellar Jubilee)/.test(p.name)) continue;
      const sentence = p.description.replace(/\s+/g, " ").split(/(?<=\.) /).find((s) => /converted into|becomes a|changed to/.test(s));
      const out = sentence ? Object.keys(OUTPUTS).filter((n) => sentence.includes(n)).map((n) => OUTPUTS[n]) : [];
      if (out.length > 0) fromKit[c.id] = out;
    }
  }
  const fromTags = Object.fromEntries(tags.filter((c) => "converts" in c).map((c) => [c.id, (c as { converts: string[] }).converts]));
  expect(fromTags).toEqual(fromKit);
});

// data/kit-overrides.json fills what genshin-db is missing (#73). The shape is checked here; each slot that is
// still empty shows as a todo, so `npm test` lists what is left to copy from the game.

const TALENT_KEYS = /^(combat[1-3]|passive[1-4]|c[1-6])$/;
type Slot = { talent: string; name: string; text: string; source: string };

test("kit-overrides.json slots name a known character and talent, with a source once filled", () => {
  const ids = new Set(tags.map((c) => c.id));
  for (const [id, c] of Object.entries(overrides.characters as Record<string, { why: string; slots: Slot[] }>)) {
    expect(ids.has(id), `${id} is not in tags.json`).toBe(true);
    for (const s of c.slots) {
      if (!s.text.trim()) continue;
      expect(s.talent, `${id}: a filled slot needs its talent`).toMatch(TALENT_KEYS);
      expect(s.source.trim(), `${id} ${s.talent}: say where the text came from`).not.toBe("");
    }
  }
});

for (const [id, c] of Object.entries(overrides.characters as Record<string, { why: string; slots: Slot[] }>)) {
  for (const s of c.slots.filter((s) => !s.text.trim())) test.todo(`kit-overrides: ${id} ${s.talent || "(which talent?)"}: ${c.why}`);
}
if (!overrides.rules.nightsoulBurst.whoCanTrigger.trim()) test.todo("kit-overrides: rules.nightsoulBurst: who can trigger it");
